window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1eb3bd252b994061"]={"versions": [{"id": "FIG-1eb3bd252b994061", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Prozess- und Werkzeugkopplungsdiagramm (Tool Interoperability Workflow) im Kontext der AUTOSAR-Methodik. Das Diagramm illustriert das Zusammenspiel zwischen AUTOSAR-Authoring-Werkzeugen und externen Verhaltensmodellierungswerkzeugen (Behavioral Modeling Tools, BMT) über ein Kopplungswerkzeug (Coupling Tool) sowie den Austausch relevanter AUTOSAR-XML-Beschreibungsdateien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Werkzeuge (Tooling / Tool Role Symbol):</strong>\n<ul class=\"fig-list\"><li><code>Coupling Tool</code>: Vermittelt zwischen AUTOSAR-SW-C-Beschreibung und externem Verhaltensmodell.\n</li><li><code>Authoring tool for editing the SWC Description</code> (angeschnitten unten links): Werkzeug für Software-Komponenten-Definition.\n</li><li><code>Authoring tool for editing the System Description</code> (angeschnitten unten Mitte): Werkzeug für Deployment und Systembeschreibung.\n</li><li><code>Authoring Tool for editing the BSW Module</code> (angeschnitten unten rechts): Werkzeug für Basissoftware-Moduldefinition.\n</li></ul>\n</li><li><strong>Artefakte / Datenmodelle:</strong>\n<ul class=\"fig-list\"><li><code>Behavioral Model</code>: Externes Verhaltensmodell (Dokumentensymbol).\n</li><li><code>.XML</code> <code>VFB Atomic Software Component</code>: AUTOSAR-XML-Beschreibung der atomaren SW-C.\n</li><li><code>.XML</code> <code>System Description</code>: AUTOSAR-Systembeschreibung.\n</li><li><code>.XML</code> <code>Basic Software Module Description</code>: AUTOSAR-BSW-Modulbeschreibung.\n</li></ul>\n</li><li><strong>Aufgaben / Prozessschritte (als abgerundete Rechtecke bzw. Chevrons):</strong>\n<ul class=\"fig-list\"><li>Innerhalb des Bereichs <code>Covered by AUTOSAR authoring tools</code>:\n<ul class=\"fig-list\"><li><code>Define VFB Application Software Component</code>\n</li><li><code>Deploy Software Component</code> (mit Verknüpfung zu einer Notiz: <em>„This task can be performed manually within an authoring tool. It is only an example of several tasks to be performed in order to modify/create a system description.“</em>)\n</li><li><code>Define BSW Module Intefaces</code> [sic]\n</li></ul>\n</li><li>Oberhalb / gekoppelt über <code>Coupling Tool</code>:\n<ul class=\"fig-list\"><li><code>Translation of SW-C Description into Behavioral Model</code> (Prozesspfeil)\n</li><li><code>Translation of Behavioral Model into SW-C Description</code> (Prozesspfeil)\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Definition der SW-C:</strong> Die Aufgabe <code>Define VFB Application Software Component</code> (unterstützt durch das entsprechende Authoring-Tool) erzeugt die <code>VFB Atomic Software Component</code> (.XML).\n</li><li><strong>Kopplung an Verhaltensmodellierung:</strong>\n<ul class=\"fig-list\"><li>Die XML-Beschreibung wird via <code>Translation of SW-C Description into Behavioral Model</code> in ein <code>Behavioral Model</code> überführt.\n</li><li>Das modifizierte oder erstellte <code>Behavioral Model</code> wird via <code>Translation of Behavioral Model into SW-C Description</code> zurück in die XML-SW-C-Beschreibung überführt.\n</li><li>Beide Übersetzungsschritte sind dem <code>Coupling Tool</code> zugeordnet.\n</li></ul>\n</li><li><strong>Systemintegration und Deployment:</strong>\n<ul class=\"fig-list\"><li>Die <code>VFB Atomic Software Component</code> fließt in den Schritt <code>Deploy Software Component</code> ein.\n</li><li><code>Deploy Software Component</code> interagiert bidirektional mit der <code>System Description</code> (.XML) (Lesen/Modifizieren bzw. Erzeugen).\n</li></ul>\n</li><li><strong>BSW-Definition:</strong>\n<ul class=\"fig-list\"><li><code>Define BSW Module Intefaces</code> interagiert bidirektional mit der <code>Basic Software Module Description</code> (.XML).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Konzeptionelle Darstellung zur werkzeuggestützten Interoperabilität gemäß AUTOSAR-Methodik.\n</li><li>Das Diagramm verdeutlicht die Trennung zwischen struktureller AUTOSAR-Modellierung (SW-C-Beschreibung) und detailliertem Verhalten (Behavioral Model).\n</li><li>Der rote Rahmen grenzt die Aufgaben ab, die typischerweise von AUTOSAR-Authoring-Tools abgedeckt werden, von den Aufgaben des externen Coupling Tools.\n</li><li>Fehlerhafter Bezeichner <code>Intefaces</code> im Schritt <code>Define BSW Module Intefaces</code> ist als Schreibfehler im Standarddokument zu beachten.\n</li></ul>"}, {"id": "FIG-9b7b3e1a46933b02", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Prozess- und Werkzeugkopplungsdiagramm (Tool Interoperability Workflow) im Kontext der AUTOSAR-Methodik. Das Diagramm illustriert das Zusammenspiel zwischen AUTOSAR-Authoring-Werkzeugen und externen Verhaltensmodellierungswerkzeugen (Behavioral Modeling Tools, BMT) über ein Kopplungswerkzeug (Coupling Tool) sowie den Austausch relevanter AUTOSAR-XML-Beschreibungsdateien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Werkzeuge (Tooling / Tool Role Symbol):</strong>\n<ul class=\"fig-list\"><li><code>Coupling Tool</code>: Vermittelt zwischen AUTOSAR-SW-C-Beschreibung und externem Verhaltensmodell.\n</li><li><code>Authoring tool for editing the SWC Description</code> (angeschnitten unten links): Werkzeug für Software-Komponenten-Definition.\n</li><li><code>Authoring tool for editing the System Description</code> (angeschnitten unten Mitte): Werkzeug für Deployment und Systembeschreibung.\n</li><li><code>Authoring Tool for editing the BSW Module</code> (angeschnitten unten rechts): Werkzeug für Basissoftware-Moduldefinition.\n</li></ul>\n</li><li><strong>Artefakte / Datenmodelle:</strong>\n<ul class=\"fig-list\"><li><code>Behavioral Model</code>: Externes Verhaltensmodell (Dokumentensymbol).\n</li><li><code>.XML</code> <code>VFB Atomic Software Component</code>: AUTOSAR-XML-Beschreibung der atomaren SW-C.\n</li><li><code>.XML</code> <code>System Description</code>: AUTOSAR-Systembeschreibung.\n</li><li><code>.XML</code> <code>Basic Software Module Description</code>: AUTOSAR-BSW-Modulbeschreibung.\n</li></ul>\n</li><li><strong>Aufgaben / Prozessschritte (durchgängig als Chevrons / Prozesspfeile dargestellt):</strong>\n<ul class=\"fig-list\"><li>Innerhalb des Bereichs <code>Covered by AUTOSAR authoring tools</code>:\n<ul class=\"fig-list\"><li><code>Define VFB Application Software Component</code>\n</li><li><code>Deploy Software Component</code> (mit Verknüpfung zu einer Notiz: <em>„This task can be performed manually within an authoring tool. It is only an example of several tasks to be performed in order to modify/create a system description.“</em>)\n</li><li><code>Define BSW Module Intefaces</code> [sic]\n</li></ul>\n</li><li>Oberhalb / gekoppelt über <code>Coupling Tool</code>:\n<ul class=\"fig-list\"><li><code>Translation of SW-C Description into Behavioral Model</code>\n</li><li><code>Translation of Behavioral Model into SW-C Description</code>\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Definition der SW-C:</strong> Die Aufgabe <code>Define VFB Application Software Component</code> (unterstützt durch das entsprechende Authoring-Tool) erzeugt die <code>VFB Atomic Software Component</code> (.XML).\n</li><li><strong>Kopplung an Verhaltensmodellierung:</strong>\n<ul class=\"fig-list\"><li>Die XML-Beschreibung wird via <code>Translation of SW-C Description into Behavioral Model</code> in ein <code>Behavioral Model</code> überführt.\n</li><li>Das modifizierte oder erstellte <code>Behavioral Model</code> wird via <code>Translation of Behavioral Model into SW-C Description</code> zurück in die XML-SW-C-Beschreibung überführt.\n</li><li>Beide Übersetzungsschritte sind dem <code>Coupling Tool</code> zugeordnet.\n</li></ul>\n</li><li><strong>Systemintegration und Deployment:</strong>\n<ul class=\"fig-list\"><li>Die <code>VFB Atomic Software Component</code> fließt in den Schritt <code>Deploy Software Component</code> ein.\n</li><li><code>Deploy Software Component</code> interagiert bidirektional mit der <code>System Description</code> (.XML) (Lesen/Modifizieren bzw. Erzeugen).\n</li></ul>\n</li><li><strong>BSW-Definition:</strong>\n<ul class=\"fig-list\"><li><code>Define BSW Module Intefaces</code> interagiert bidirektional mit der <code>Basic Software Module Description</code> (.XML).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Konzeptionelle Darstellung zur werkzeuggestützten Interoperabilität gemäß AUTOSAR-Methodik.\n</li><li>Das Diagramm verdeutlicht die Trennung zwischen struktureller AUTOSAR-Modellierung (SW-C-Beschreibung) und detailliertem Verhalten (Behavioral Model).\n</li><li>Der rote Rahmen grenzt die Aufgaben ab, die typischerweise von AUTOSAR-Authoring-Tools abgedeckt werden, von den Aufgaben des externen Coupling Tools.\n</li><li>Fehlerhafter Bezeichner <code>Intefaces</code> im Schritt <code>Define BSW Module Intefaces</code> ist als Schreibfehler im Standarddokument zu beachten.\n</li></ul>"}], "trans": [{"from": "FIG-1eb3bd252b994061", "to": "FIG-9b7b3e1a46933b02", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Die drei Prozessschritte innerhalb des rot hinterlegten Bereichs („Covered by AUTOSAR authoring tools“) wurden von abgerundeten Rechtecken in Chevron- bzw. Pfeilsymbole (Prozessschrittform analog zu den oberen Translationsschritten) geändert:\n<ul class=\"fig-list\"><li>„Define VFB Application Software Component“\n</li><li>„Deploy Software Component“\n</li><li>„Define BSW Module Intefaces“\n</li></ul>\n</li><li>Die Beschriftungen dieser drei Aufgaben sind nun direkt unter bzw. außerhalb der jeweiligen Chevron-Symbole platziert statt zentriert im Kasten.\n</li><li>Zeilenumbruch im Textblock rechts neben dem Pfeil „Translation of Behavioral Model into SW-C Description“ leicht angepasst.\n</li></ul>"}]};
